uniform sampler2D uB;
uniform float uP;
uniform int uType;
uniform float uOpA;
uniform float uOpB;
vec4 A(vec2 uv) { return (uv.x < 0.0 || uv.y < 0.0 || uv.x > 1.0 || uv.y > 1.0) ? vec4(0.0) : texture(uTex, uv) * uOpA; }
